"use client";
import { Check, Moon, Sun } from "lucide-react";
import { Panel } from "@/components/admin/panel";
import { useTheme } from "@/components/theme-provider";
export function VendorAppearance() { const { theme, setTheme } = useTheme(); return <Panel title="Theme" description="Choose your portal appearance. Your preference is saved to this device."><div className="grid gap-3 sm:grid-cols-2">{(['dark', 'light'] as const).map(value => <button key={value} type="button" aria-pressed={theme === value} onClick={() => setTheme(value)} className={`rounded-xl border p-3 text-left ${theme === value ? 'border-gold ring-1 ring-gold' : 'border-line'}`}><span aria-hidden className={`mb-3 flex h-24 gap-2 rounded-lg p-2 ${value === 'dark' ? 'bg-[#0e1712]' : 'bg-[#f8f8f5]'}`}><span className={`w-1/4 rounded ${value === 'dark' ? 'bg-[#1b2a20]' : 'bg-white'}`}/><span className="flex flex-1 flex-col gap-2"><span className="h-3 w-1/2 rounded bg-gold"/><span className={`flex-1 rounded border ${value === 'dark' ? 'border-[#29392c] bg-[#1b2a20]' : 'border-[#dce4d8] bg-white'}`}/></span></span><span className="flex items-center gap-2 text-sm font-semibold">{value === 'dark' ? <Moon className="h-4 w-4"/> : <Sun className="h-4 w-4"/>}{value === 'dark' ? 'Dark' : 'Light'}{theme === value ? <Check className="ml-auto h-4 w-4 text-goldink"/> : null}</span></button>)}</div></Panel>; }
